'use client';

import type { FormEventHandler } from 'react';
import { useState } from 'react';
import { Button } from '@/registry/react/ui/button';
import {
  Card,
  CardBody,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/registry/react/ui/card';
import { Field, FieldErrorText } from '@/registry/react/ui/field';
import {
  PinInput,
  PinInputHiddenInput,
  PinInputLabel,
  PinInputControl,
  PinInputInputs,
} from '@/registry/react/ui/pin-input';
import styles from './verification-code-form.module.css';

export function VerificationCode({ onSubmit }: { onSubmit?: FormEventHandler<HTMLFormElement> }) {
  const [invalid, setInvalid] = useState(false);

  const handleSubmit: FormEventHandler<HTMLFormElement> = (event) => {
    const code = new FormData(event.currentTarget).get('code');
    const isComplete = typeof code === 'string' && code.length === 6;

    setInvalid(!isComplete);

    if (!isComplete) {
      event.preventDefault();
      return;
    }

    onSubmit?.(event);
  };

  return (
    <Card className={styles.root}>
      <CardHeader className={styles.header}>
        <CardTitle>Verify your email</CardTitle>
        <CardDescription>Enter the 6-digit code from your email.</CardDescription>
      </CardHeader>

      <CardBody>
        <form className={styles.stack} noValidate onSubmit={handleSubmit}>
          <Field className={styles.field} invalid={invalid} required>
            <PinInput
              className={styles.code}
              count={6}
              name="code"
              otp
              onValueChange={() => setInvalid(false)}
            >
              <PinInputLabel>Verification code</PinInputLabel>
              <PinInputHiddenInput />
              <PinInputControl>
                <PinInputInputs />
              </PinInputControl>
            </PinInput>
            {invalid ? (
              <FieldErrorText>Enter all six digits before verifying.</FieldErrorText>
            ) : null}
          </Field>

          <Button type="submit" className={styles.submit}>
            Verify email
          </Button>
        </form>
      </CardBody>

      <CardFooter className={styles.footer}>
        <p>
          Wrong email?{' '}
          <a className={styles.link} href="/sign-in">
            Use a different one
          </a>
        </p>
      </CardFooter>
    </Card>
  );
}

.root {
  width: min(100%, 26rem);
}

.header {
  display: flex;
  flex-direction: column;
  gap: var(--moduix-spacing-2);
  text-align: center;
}

.stack {
  display: grid;
  gap: var(--moduix-spacing-4);
}

.field {
  align-items: center;
}

.code[data-slot='pin-input-root'] {
  --moduix-pin-input-root-gap: var(--moduix-spacing-2);
  align-items: center;
  width: 100%;
}

.link {
  color: var(--moduix-color-primary);
  font-size: var(--moduix-text-sm);
  font-weight: var(--moduix-weight-medium);
  text-underline-offset: 0.2em;

  &:hover {
    color: var(--moduix-color-foreground);
    text-decoration: underline;
  }

  &:focus-visible {
    outline: var(--moduix-border-width-md) solid var(--moduix-color-ring);
    outline-offset: var(--moduix-border-width-sm);
    border-radius: var(--moduix-radius-xs);
  }
}

.submit {
  width: 100%;
}

.footer {
  justify-content: center;
  text-align: center;
}

.footer p {
  margin: 0;
  color: var(--moduix-color-muted-foreground);
  font-size: var(--moduix-text-sm);
}
